# Logic: Simulating Geo-Location Anomalies & Velocity Fraud
def is_fraudulent_transaction(cust_city, merchant_city, time_diff, amount, limit):
    fraud_score = 0

    # Geo-mismatch: POS transaction 1000km away within 1 hour
    if cust_city != merchant_city and time_diff.seconds < 3600:
        fraud_score += 50

    # Credit limit breach: Sudden 95% utilization
    if (amount / limit) > 0.95:
        fraud_score += 40

    return 1 if fraud_score >= 80 else 0
